    int L=rng()%n+1; if(L<1)L=1;
    int W=rng()%L+1;
    int maxi=n-L-W+1; if(maxi<=0) continue;
    int i0=rng()%(maxi+1);
    // brute
    long long best=LLONG_MIN;
    for(int j=i0;j<=i0+W-1;j++){ long long mn=LLONG_MAX; for(int k=j;k<j+L;k++)mn=min(mn,p[k]); best=max(best,mn);}
    // formula
    long long got;
    int cs=i0+W-1, ce=i0+L-1;
    long long cmin=LLONG_MAX; for(int k=cs;k<=ce;k++)cmin=min(cmin,p[k]);
    if(W==1) got=cmin;
    else{
      int ls=i0, le=i0+W-2, rs=i0+L, re=i0+L+W-2;
      auto f=[&](int qq)->long long{ if(qq>=W-1) return LLONG_MAX; long long m=LLONG_MAX; for(int k=i0+qq;k<=i0+W-2;k++)m=min(m,p[k]); return m;};
      auto g=[&](int qq)->long long{ if(qq<=0) return LLONG_MAX; long long m=LLONG_MAX; for(int k=i0+L;k<=i0+L+qq-1;k++)m=min(m,p[k]); return m;};
      int lo=0,hi=W-1;
      while(lo<hi){int mid=(lo+hi+1)/2; if(f(mid)<=g(mid))lo=mid; else hi=mid-1;}
      long long Y=0;
      for(int qq=max(0,lo-1);qq<=min(W-1,lo+1);qq++) Y=max(Y,min(f(qq),g(qq)));
